template:
% 参数由系统自动注入：\def\base{2} \def\showcompare{0} \def\showfixed{1} \def\showpoint{0} \def\px{1.5} \def\labelp{P}
% 点 P 纵坐标 a^px；x 视图对称纳入点 P
\pgfmathsetmacro{\py}{pow(\base,\px)}
\pgfmathsetmacro{\v}{max(3.0, abs(\px)+0.8)}
\pgfmathtruncatemacro{\xleft}{-floor(\v)}
\pgfmathtruncatemacro{\xright}{ceil(\v)}
% y 视图：以定点 (0,1) 与点 P 为特征，曲线过高处封顶 8 个单位
\pgfmathsetmacro{\ytopfeat}{max(1,\py)}
\pgfmathsetmacro{\yedgeL}{pow(\base,\xleft)}
\pgfmathsetmacro{\yedgeR}{pow(\base,\xright)}
\pgfmathsetmacro{\ytop}{min(max(\yedgeL,\yedgeR),\ytopfeat+8.0)+0.8}
\pgfmathtruncatemacro{\ytop}{ceil(\ytop)}
\pgfmathtruncatemacro{\ybottom}{-1}
% 曲线绘制域：y 到达视图上边时截断（ln 为自然对数）
\pgfmathsetmacro{\xexit}{ln(\ytop+0.3)/ln(\base)}
\ifdim\base pt>1pt
  \pgfmathsetmacro{\dlo}{\xleft}
  \pgfmathsetmacro{\dhi}{min(\xright,\xexit)}
\else
  \pgfmathsetmacro{\dlo}{max(\xleft,\xexit)}
  \pgfmathsetmacro{\dhi}{\xright}
\fi
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$};
  \node[below left, font=\tiny] at (0,0) {$O$};
  \foreach \x in {\xleft,...,\xright} {
    \ifnum\x=0\else
      \draw (\x,0.12/\figscale) -- (\x,-0.12/\figscale);
      \node[below, font=\tiny, inner sep=1pt] at (\x,0) {$\x$};
    \fi
  }
  \foreach \y in {\ybottom,...,\ytop} {
    \ifnum\y=0\else
      \draw (0.12/\figscale,\y) -- (-0.12/\figscale,\y);
      \node[left, font=\tiny, inner sep=1pt] at (0,\y) {$\y$};
    \fi
  }
  % ===== 对比曲线 y=(1/a)^x（关于 y 轴对称，虚线）=====
  \ifnum\showcompare>0
    \ifdim\base pt>1pt
      \pgfmathsetmacro{\clo}{max(\xleft,-\xexit)}
      \pgfmathsetmacro{\chi}{\xright}
      \draw[dashed, gray, thick, domain=\clo:\chi, samples=80, smooth] plot (\x, {pow(\base,-\x)});
      \node[above left, font=\tiny, gray] at (\clo+0.2,\ytop-0.4) {$y=(\frac{1}{a})^x$};
    \else
      \pgfmathsetmacro{\clo}{\xleft}
      \pgfmathsetmacro{\chi}{min(\xright,-\xexit)}
      \draw[dashed, gray, thick, domain=\clo:\chi, samples=80, smooth] plot (\x, {pow(\base,-\x)});
      \node[above right, font=\tiny, gray] at (\chi-0.2,\ytop-0.4) {$y=(\frac{1}{a})^x$};
    \fi
  \fi
  % ===== 主曲线 y=a^x =====
  \draw[thick, domain=\dlo:\dhi, samples=100, smooth] plot (\x, {pow(\base,\x)});
  \ifdim\base pt>1pt
    \node[above right, font=\tiny] at (\dhi-0.2,\ytop-0.9) {$y=a^x$};
  \else
    \node[above left, font=\tiny] at (\dlo+0.2,\ytop-0.9) {$y=a^x$};
  \fi
  % ===== 定点 (0,1) =====
  \ifnum\showfixed>0
    \fill (0,1) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (0,1) {$(0,1)$};
  \fi
  % ===== 曲线上点 P =====
  \ifnum\showpoint>0
    \fill (\px,\py) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
  \fi
\end{tikzpicture}
